#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="C:\Users\HONOR\Documents\React\personal-poems\node_modules\.pnpm\find-process@2.1.1\node_modules\find-process\dist\cjs\bin\node_modules;C:\Users\HONOR\Documents\React\personal-poems\node_modules\.pnpm\find-process@2.1.1\node_modules\find-process\dist\cjs\node_modules;C:\Users\HONOR\Documents\React\personal-poems\node_modules\.pnpm\find-process@2.1.1\node_modules\find-process\dist\node_modules;C:\Users\HONOR\Documents\React\personal-poems\node_modules\.pnpm\find-process@2.1.1\node_modules\find-process\node_modules;C:\Users\HONOR\Documents\React\personal-poems\node_modules\.pnpm\find-process@2.1.1\node_modules;C:\Users\HONOR\Documents\React\personal-poems\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/c/Users/HONOR/Documents/React/personal-poems/node_modules/.pnpm/find-process@2.1.1/node_modules/find-process/dist/cjs/bin/node_modules:/mnt/c/Users/HONOR/Documents/React/personal-poems/node_modules/.pnpm/find-process@2.1.1/node_modules/find-process/dist/cjs/node_modules:/mnt/c/Users/HONOR/Documents/React/personal-poems/node_modules/.pnpm/find-process@2.1.1/node_modules/find-process/dist/node_modules:/mnt/c/Users/HONOR/Documents/React/personal-poems/node_modules/.pnpm/find-process@2.1.1/node_modules/find-process/node_modules:/mnt/c/Users/HONOR/Documents/React/personal-poems/node_modules/.pnpm/find-process@2.1.1/node_modules:/mnt/c/Users/HONOR/Documents/React/personal-poems/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
