}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../find-process/dist/cjs/bin/find-process.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../find-process/dist/cjs/bin/find-process.js" $args
